function sortedArrayToBST(nums) {
  if (nums.length === 0) return null;
  const mid0 = Math.floor((nums.length - 1) / 2);
  const root = new TreeNode(nums[mid0]);
  const stack = [[root, 0, mid0 - 1, "left"], [root, mid0 + 1, nums.length - 1, "right"]];
  while (stack.length > 0) {
    const [parent, lo, hi, side] = stack.pop();
    if (lo > hi) continue;
    const mid = Math.floor((lo + hi) / 2);
    const node = new TreeNode(nums[mid]);
    parent[side] = node;                   // attach, then split this range
    stack.push([node, lo, mid - 1, "left"], [node, mid + 1, hi, "right"]);
  }
  return root;
}

TreeNode sortedArrayToBST(int[] nums) {
    if (nums.length == 0) return null;
    int mid0 = (nums.length - 1) / 2;
    TreeNode root = new TreeNode(nums[mid0]);
    Deque<Object[]> stack = new ArrayDeque<>();
    stack.push(new Object[] {root, 0, mid0 - 1, true});
    stack.push(new Object[] {root, mid0 + 1, nums.length - 1, false});
    while (!stack.isEmpty()) {
        Object[] job = stack.pop();
        TreeNode parent = (TreeNode) job[0];
        int lo = (int) job[1], hi = (int) job[2];
        if (lo > hi) continue;
        int mid = (lo + hi) / 2;
        TreeNode node = new TreeNode(nums[mid]);
        if ((boolean) job[3]) parent.left = node;    // attach, then split this range
        else parent.right = node;
        stack.push(new Object[] {node, lo, mid - 1, true});
        stack.push(new Object[] {node, mid + 1, hi, false});
    }
    return root;
}

TreeNode* sortedArrayToBST(vector<int>& nums) {
    if (nums.empty()) return nullptr;
    int mid0 = ((int)nums.size() - 1) / 2;
    TreeNode* root = new TreeNode(nums[mid0]);
    // (parent, lo, hi, attach on the left?)
    vector<tuple<TreeNode*, int, int, bool>> stack = {{root, 0, mid0 - 1, true}, {root, mid0 + 1, (int)nums.size() - 1, false}};
    while (!stack.empty()) {
        auto [parent, lo, hi, left] = stack.back();
        stack.pop_back();
        if (lo > hi) continue;
        int mid = (lo + hi) / 2;
        TreeNode* node = new TreeNode(nums[mid]);
        (left ? parent->left : parent->right) = node;  // attach, then split this range
        stack.push_back({node, lo, mid - 1, true});
        stack.push_back({node, mid + 1, hi, false});
    }
    return root;
}
